#!/usr/bin/env node
/* =============================================================================
   tools/apply_zigtouch_wave.mjs — THE NUCLEUS AND THE WAVE  ·  2026-09-22
   ZigTouch 0.1.1 · ZigHaptics 0.1.1 · touch lab v0.2
   run from the repo root (C:\Users\billy\Zigverse):
     node tools\apply_zigtouch_wave.mjs --dry-run
     node tools\apply_zigtouch_wave.mjs --gates

   SELF-SUFFICIENT: works whether or not apply_zigtouch.mjs was run first —
   it carries every ZigTouch file and appends whichever Session_Log entries
   are missing, in order. Base64 payload, sha256-verified after writing;
   files that already match are left alone. No existing engine, species or
   host file is touched.

   CHANGES
     engine/zigtouch.js          0.1.1 — the WAVE event; stopped-finger velocity fix
     engine/zighaptics.js        0.1.1 — the wave swell
     test/zigtouch_ref.mjs       +4 wave cases
     test/zighaptics_ref.mjs     +1 wave case
     zigtouch_lab.html           v0.2 — nucleus on hold, wave on a moving release
     dist/ZigTouch_Lab_v0.2.html open this on the phone
     dist/ZigTouch_Lab_v0.1.html kept, for A/B against v0.2
   ========================================================================== */
import { readFileSync, writeFileSync, existsSync, mkdirSync, appendFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import path from "node:path";
const DRY = process.argv.includes("--dry-run"), GATES = process.argv.includes("--gates");
const sha = (b) => createHash("sha256").update(b).digest("hex");
const PAYLOAD = [{"path": "engine/zigtouch.js", "sha": "91fbab27666bb1348c8d8b4686fb0479c0a9979e72fd7bbae7032e6b2c8d80ce", "b64": ""}, {"path": "engine/zighaptics.js", "sha": "6ca0147108c86d433a15dc112745760cde7be79c8e85bac7e9070910e0d8af59", "b64": ""}, {"path": "test/zigtouch_ref.mjs", "sha": "d072183717f05681df6e1458709455dd5c16996132ba25e32e22f2838bec63e9", "b64": ""}, {"path": "test/zighaptics_ref.mjs", "sha": "02a387c6cbf37fba4142579daea10c1af68492fce30e53d508f72e1860b363d6", "b64": ""}, {"path": "zigtouch_lab.html", "sha": "4a911bf30a57ba1ede0d097c2a4237e9219957de8de92a83808a57f9a18883ae", "b64": ""}, {"path": "dist/ZigTouch_Lab_v0.2.html", "sha": "ee85345dc47b354c198402079efc888b73f9d109b95905b4086cf68889034274", "b64": ""}, {"path": "dist/ZigTouch_Lab_v0.1.html", "sha": "c6d360071be0d8e3ca13d69c266f172d73da3938327a868207b24850590ee8fc", "b64": ""}];
const LOGS = [["ZIGTOUCH + ZIGHAPTICS \u2014 a touch is weather", "\n\n**2026-09-22 \u00b7 ZIGTOUCH + ZIGHAPTICS \u2014 a touch is weather, not a command** \u00b7 ZigTouch **0.1.0** \u00b7 ZigHaptics **0.1.0** \u00b7 engine files untouched\n\n**Why.** Scout's viability brief reframed the phone app as a living-world instrument (WATCH \u2192 TOUCH \u2192 CONDUCT, one organism). v5.3's touch was a performer's touch: press = `Perf.hold()`, lift < 220ms = `Sickle.strike()` \u2014 right for the Bee, wrong for someone who wants something to attend to. A finger that commands turns watching into operating.\n\n**ZigTouch** (`engine/zigtouch.js`, pure logic + a DOM adapter). Tap = startle + orient, habituating (tenth tap at 2Hz earns 31% of the first; 12s of quiet restores 94%; a tap somewhere new partly dishabituates). Hold = trust on the charisma curve (two smoothing stages, 0.01 at 0.5s \u2192 0.85 at 4s), felt as a heartbeat that slows as trust rises, and trust outlives the hand. Stroke = a current with position/velocity/strength that decays after lift; slow soothes, fast stirs. Settle after contact. Four memory layers: seconds (habituation, arousal) \u00b7 minutes (mood.agitation/ease) \u00b7 session (familiarity) \u00b7 persistent (trait drift \u2264 0.03/session, JSON the host stores). **Fixed 120Hz clock with timestamped inputs \u2014 the same gestures give byte-identical field and feelings at 30/60/120/144fps and an irregular cadence.** Coordinates in surface units (1 = shorter side) so a lobby screen inherits it. Files itself in the Canon as `touch-field` (experience).\n\n**ZigHaptics** (`engine/zighaptics.js`). Feelings \u2192 platform. Android web `navigator.vibrate` WORKS (duration only \u2014 strength becomes length). iOS native via `@capacitor/haptics` STUBBED and proven against a fake plugin (HEAVY/MEDIUM/LIGHT by strength). iOS 18 Safari switch-tick EXPERIMENTAL, opt-in. Otherwise graceful silence with `onVisual` for light. Priority rate-limit; a floor below which feelings are shown, not buzzed.\n\n**Lab** `zigtouch_lab.html` \u2192 `dist/ZigTouch_Lab_v0.1.html` (45 KB, 2D canvas so it opens on any phone). A small spindle/lens that READS the field only.\n\n**Passed:** `node --check` clean \u00b7 reference gate **48/48** (+`zigtouch_ref`, `zighaptics_ref`) \u00b7 headless Pixel 7 drive of the bundle: tap/hold/stroke produce the three vibrate signatures, 61 rAF/s, 0 errors. **Not run:** boot gate / Metal gate \u2014 no WebGPU file changed.\n\n**Open:** Bill's hand on a real Android phone (the only gate for feel) \u00b7 `legacyBridge` into the v5.3 WebGPU host (startle \u2192 strike, hold \u2192 Perf.hold scaled by trust) \u00b7 **stroke has no GPU consumer** \u2014 `field.current` waits for the flow kernel to read ZigField \u00b7 ZigSense/ZigField proper (touch is its first input; mic-as-weather next) \u00b7 Capacitor shell for iOS \u00b7 Core Haptics custom plugin for continuous heartbeat intensity \u00b7 the lab has no panel gate either.\n"], ["THE NUCLEUS AND THE WAVE", "\n\n**2026-09-22 (later) \u00b7 THE NUCLEUS AND THE WAVE** \u00b7 ZigTouch **0.1.0 \u2192 0.1.1** \u00b7 ZigHaptics **0.1.0 \u2192 0.1.1** \u00b7 touch lab **v0.2** \u00b7 engine files untouched\n\n**Bill, on the lab:** \"It feels like my movements are the nucleus of the organism.\" Then the decision: **nucleus when they hold the screen, then a wave can send the shards away with the current.** This is PRESENCE reached from the touch side \u2014 a held finger earning trust is a held note earning charisma \u2014 so the GPU port should make a trusted touch point the Bee's position rather than a second system.\n\n**ZigTouch 0.1.1 \u2014 THE WAVE.** A stroke released while still moving (\u2265 `waveSpeed` 0.9 u/s) emits `wave` with direction, speed, and `gathered` (the trust at release); strength = speed \u00d7 (0.4 + 0.6\u00b7trust), so a wave from a nucleus carries 0.67 against 0.32 from an open hand. Stop, then lift \u2192 `release`, never a wave. **Fault found by the new proof:** a finger that stops sends no more move events, so its last velocity froze \u2014 a stopped finger would have thrown a wave, and a paused stroke kept pushing its current. Velocity now bleeds away after 40 ms of silence on the wire.\n\n**ZigHaptics 0.1.1:** `wave` renders as a swell that runs off the hand ([36,45,23,60,14] strong \u00b7 [20,45,13,60,9] weak); Capacitor maps it to MEDIUM/LIGHT with a dub.\n\n**Lab v0.2** (`dist/ZigTouch_Lab_v0.2.html`). Hold \u2192 trusted shards gather into a small lens around the finger (each keeps its place in the body, scaled down, so the nucleus has a shape). Wave \u2192 only what was gathered is launched along the hand's velocity, fanned into a swell; the body's spring loosens (scatter \u03c4 2.2 s) so it travels, then comes home and settles. **First draft was a cannon** \u2014 the whole body left the glass (light centroid 205 \u2192 351 px of 412). Fixed with a launch cap, gathered-only launch, and a braking cushion at the edge: now 205 \u2192 170 on the hold (light at the finger \u00d72.1) \u2192 ~290 after the wave \u2192 205 home by 9.5 s, settle felt. Dials: `#nucleus=0..2` \u00b7 `#throw=0.2..2`.\n\n**Passed:** `node --check` clean \u00b7 reference gate **48/48** (zigtouch_ref +4 wave cases, zighaptics_ref +1) \u00b7 headless Pixel 7: hold \u2192 wave \u2192 home measured by pixel probe, 0 errors.\n\n**Open:** Bill's hand on the dials (nucleus strength, throw distance, whether a flick may reach the edge) \u00b7 the GPU port \u2014 Option A (legacyBridge) vs B (ZigField read by the compute kernel), with the touch nucleus as the Bee's position \u00b7 the nucleus/wave behaviours are lab code today; they become engine laws in B.\n"]];
console.log("apply_zigtouch_wave.mjs — the nucleus and the wave\n");
if (!existsSync("engine/zigcore.js")) { console.log("  FAIL  engine/zigcore.js not found — run from the repo root."); process.exit(1); }
let bad = 0;
for (const p of PAYLOAD) {
  const want = Buffer.from(p.b64, "base64");
  if (sha(want) !== p.sha) { console.log("  FAIL  payload corrupt: " + p.path); bad++; continue; }
  if (existsSync(p.path) && sha(readFileSync(p.path)) === p.sha) { console.log("  UNCHANGED  " + p.path); continue; }
  const verb = existsSync(p.path) ? "REPLACE" : "ADD";
  if (DRY) { console.log("  would " + verb + "  " + p.path + "  (" + want.length + " bytes)"); continue; }
  mkdirSync(path.dirname(p.path), { recursive: true });
  writeFileSync(p.path, want);
  const ok = sha(readFileSync(p.path)) === p.sha;
  console.log((ok ? "  " + verb + " ✓  " : "  FAIL  ") + p.path + "  sha256 " + p.sha.slice(0, 12));
  if (!ok) bad++;
}
const LP = "briefs/Session_Log.md";
if (existsSync(LP)) for (const [mark, text] of LOGS) {
  if (readFileSync(LP, "utf8").includes(mark)) { console.log("  UNCHANGED  " + LP + "  (" + mark.slice(0, 28) + "…)"); continue; }
  if (DRY) console.log("  would APPEND  " + LP + "  (" + mark.slice(0, 28) + "…)");
  else { appendFileSync(LP, text); console.log("  APPEND ✓  " + LP + "  (" + mark.slice(0, 28) + "…)"); }
}
if (bad) { console.log("\n" + bad + " FAILED — nothing above marked FAIL can be trusted."); process.exit(1); }
if (GATES && !DRY) {
  for (const t of ["test/zigtouch_ref.mjs", "test/zighaptics_ref.mjs"]) {
    try { const out = execFileSync(process.execPath, [t], { encoding: "utf8" }); console.log("  " + out.trim().split("\n").pop() + "  (" + t + ")"); }
    catch (e) { console.log("  FAIL  " + t + "\n" + (e.stdout || "")); process.exit(1); }
  }
}
console.log(DRY ? "\ndry run — nothing written." : "\ninstalled and verified. Next: git add, commit, push.");
